D.ClientTexts.JournalSection[13107]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["236be1c3c918b2f6:576"]="古尔丹开始进行仪式，让他的主人进入艾泽拉斯。他把自己锁在活动的阿曼苏尔之眼中，并召唤他的恶魔副官。然而在玩家靠近活动的阿曼苏尔之眼时，也会获得同样强大的技能。技能会根据其担任的角色产生变化。\r\n\r\n副官被击败后，古尔丹会亲自加入战斗，用邪能强化自己脆弱的体格。生命值在85%、70%和55%时，古尔丹将再次跳进活动的阿曼苏尔之眼，以强化他的技能。\r\n\r\n生命值进一步减少后，古尔丹会乞求他的燃烧军团主人赐予更多力量，从而释放出他的终极力量，同时阻止玩家从阿曼苏尔之眼获得帮助。"}}
