D.ClientTexts.JournalSection[13145]={Name={["529586c1022f52b2:25"]="第二阶段：主人的力量"},Description={["32ae4b021e2cc22d:128"]="生命值降至50%时，古尔丹会驱动阿曼苏尔之眼的力量，获取经过强化的新技能，并干扰玩家从阿曼苏尔之眼中获取力量。"}}
