D.ClientTexts.JournalSection[13179]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["f41a2295665b7220:444"]="玩家在战斗开始时与伊格诺斯的眼柄和触须交战，而巨大的眼睛会挡住通往树木中心的路。击败这些触须后，会刷出活动的梦魇脓液，玩家可以在眼睛附近摧毁梦魇脓液来对眼睛造成伤害。\r\n\r\n一旦眼睛被击败，玩家就可以在一段时间内进入树木的中空区域，直接对伊格诺斯造成伤害。然后眼睛会重新成形，再度封锁住通向中空区域的入口，并且杀死所有还留在区域内的玩家。这个过程会反复持续，直到玩家击败伊格诺斯为止。"}}
