D.ClientTexts.JournalSection[13335]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["1b0000fe903e1459:263"]="堕落的塞纳留斯会周期性地创造梦魇之种，种子会在一段时间后发芽，召唤一个梦魇盟友。梦魇盟友必须被击败。玛法里奥会在战斗中帮忙，并且净化附近玩家数量最多的梦魇之种，从而净化盟友，令盟友转而帮助玩家团队。"}}
