D.ClientTexts.JournalSection[13675]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["68a63a588ae484bd:285"]="高级植物学家特尔安会使用奥术、自然和日光魔法来保卫他的花园。他的剩余生命值到达75%和50%的时候，他会分离自己的能量，形成专注于某个特定魔法系的强化形体。这样的分离会夺走他施放该系魔法的能力，但是会令那个形体获得新技能。"}}
D.ClientTexts.JournalSection[13676]={Name={["63470d24fac96deb:13"]=S[1438]}}
D.ClientTexts.JournalSection[13677]={Name={["10692d869ec5e909:5"]="坦克"}}
