D.ClientTexts.JournalSection[13681]={Name={["ed8441a537abe01a:18"]="第二阶段：昼夜分裂"},Description={["10125fb87eb4722b:126"]="高级植物学家特尔安的生命值降到75%时，他会牺牲他施放日光魔法的能力，创造一个强化的日光镜像。"}}
D.ClientTexts.JournalSection[13682]={Name={["ed724be30ec4ff88:15"]=S[13658]}}
D.ClientTexts.JournalSection[13683]={Name={["052a748ef3c7a4dd:20"]="第三阶段：纯净形态"},Description={["a23f627f480dd536:120"]="高级植物学家特尔安的生命值降到50%时，他会把他剩余的力量分给一个强化的自然镜像和强化的奥术镜像。"}}
