D.ClientTexts.JournalSection[14208]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["d2d4dd2eb1b90a73:385"]="海拉会用她的超自然力量召唤宝珠，污染敌人，喷吐淤泥并碾压她的敌人。\r\n\r\n生命值降至65%时，海拉会离开海底，号令冥狱深渊的居民或噬魂之喉的海浪远程攻击玩家团队。击败海拉的触须可对其造成伤害，使其回到海滩上。\r\n\r\n然后，海拉会命令冥狱深渊的部队背水一战，同时使用冥狱深渊的爪牙和她的超自然力量攻击，直到被击败。"}}
