D.ClientTexts.JournalSection[14885]={Name={["ff03ccb75419e6a2:27"]=S[17670]},Description={["a18218d2bb2fa13f:180"]="古尔丹把自己锁在激活的阿曼苏尔之眼中，并召唤他的恶魔副官。玩家靠近活动的阿曼苏尔之眼时，会根据自己所担任的角色而获得旗鼓相当的不同技能。"}}
