D.ClientTexts.JournalSection[14917]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["ca42a6a1e6e1ab4c:707"]="玩家在基尔加丹的指挥舰上与他交战，战斗中除了基尔加丹，还有他用自己的意志扭曲玩家战友的暗影映像。\r\n\r\n生命值达到80%时，基尔加丹会飞上天空，向玩家发射报复性的攻击弹幕，然后他会带着更强大的力量继续与玩家战斗。\r\n\r\n生命值达到40%时，基尔加丹会用黑暗包裹平台，令玩家的视野局限在周围很小的范围里，并会召唤数个暗影之魂。玩家必须在黑暗中找到伊利丹，伊利丹会和玩家共享视野。玩家要利用伊利丹的无目凝视来击败暗影之魂并驱散黑暗。\r\n\r\n玩家逃离黑暗后，基尔加丹到达了阿古斯，并释放了他的最终攻击——千魂之暗。玩家必须使用他打开的裂隙来吸收千魂之暗的飞弹，避免被杀死。"}}
