D.ClientTexts.JournalSection[15399]={Name={["80d8b1273b543c5a:20"]=S[1308]},Description={["523e9b4332397ed0:115"]="伊利丹会在欺诈者的遮蔽阶段飞到平台上。玩家只要在他身边8码之内，就会获得伊利丹的无目凝视。"}}
