D.ClientTexts.JournalSection[15550]={Name={["070ac95a5a597ca7:13"]=S[19002]},Description={["b43817a70abcc368:195"]="在贝拉克的牢笼中凝聚成形的巨大灵魂，被囚禁并折磨了数千年。虽然从表面上看，它不过是一团恶意与痛苦的集合体，但它的内部依然存在着早已被遗忘的囚犯们残存的希望。"}}
