D.ClientTexts.JournalSection[15578]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["71519de3533a3aee:251"]="每隔一段时间，高阶督军纳因图斯就会用穿刺之脊刺穿玩家，使其昏迷，直到被盟友解救为止。在战斗过程中，纳因图斯会施放海潮之盾，免疫伤害，并逐渐恢复生命，直到玩家投掷穿刺之脊刺穿气泡为止。"}}
