D.ClientTexts.JournalSection[15599]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["daf9e7d930f76332:233"]="本场战斗的目标是协助阿卡玛击败阿卡玛之影。击败灰舌导魔师和灰舌巫师，让阿卡玛之影来到阿卡玛身边，然后开启第二阶段。第二阶段开始后，需要在阿卡玛死亡之前击败阿卡玛之影，以赢得战斗的胜利。"}}
