D.ClientTexts.JournalSection[15799]={Name={["18225ef7a16a7418:14"]="平台：枢纽"},Description={["a8574793d423c7b8:42"]="连接军团传送门的中央平台。"}}
D.ClientTexts.JournalSection[15800]={Name={["347365e89825d38f:15"]="平台：克索诺斯"},Description={["bc2739a4e5a7b6d5:40"]="从克索诺斯涌出的烈焰和火焰恶魔。"}}
D.ClientTexts.JournalSection[15801]={Name={["d40b736ac8ff9813:16"]="平台：拉恩科纳"},Description={["b798bb344dcf5dab:54"]="许多行动敏捷的恶魔都是来自被邪能浸透的拉恩科纳。"}}
D.ClientTexts.JournalSection[15802]={Name={["b2cd6ce1e0a17768:17"]="平台：纳斯雷萨"},Description={["295fe8ee8077a41f:56"]="纳斯雷萨世界充斥着蛰伏的暗影和欺骗。"}}
D.ClientTexts.JournalSection[15803]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["aadf8c2b99fdf09e:510"]="传送门守护者哈萨贝尔为燃烧军团掌管着传送枢纽，调度着往来于前线的恶魔大军。\r\n\r\n当生命值降至90%时，哈萨贝尔会打开通往克索诺斯的烈焰传送门烧灼她的敌人。乌坎纳会通过传送门到达战场，并强化这座传送门直至死亡。\r\n\r\n当生命值降至60%时，哈萨贝尔会打开通往拉恩科纳的邪能传送门溶解她的敌人。达西迪奥夫人会通过传送门到达战场，并强化这座传送门直至死亡。\r\n\r\n当生命值降至30%时，哈萨贝尔会打开通往纳斯雷萨的暗影传送门以混淆敌人的心智。领主埃尔加会通过传送门到达战场，并强化这座传送门直至死亡。"}}
D.ClientTexts.JournalSection[15804]={Name={["938cdd6182898d14:8"]="乌坎纳"}}
