D.ClientTexts.JournalSection[15826]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["e649e0a116949d04:459"]="破坏魔女巫会的主母们共享生命值。两个破坏魔主母会留在竞技场内直接与敌人战斗，与此同时泰坦之魂会受到折磨。在迫使两个泰坦之魂使用自身技能对付女巫会的敌人后，破坏魔主母们会交换位置。\r\n\r\n当彼此间的距离少于18码时，破坏魔女巫会受到的伤害降低。击败女巫会的关键在于击败被折磨的泰坦幽灵并释放阿曼苏尔、高戈奈斯、卡兹格罗斯和诺甘农的灵魂。"}}
