D.ClientTexts.JournalSection[16345]={Name={["2b03a77ea9314c31:10"]=S[10333]},Description={["3c1d34a920758b94:127"]="帕拉克希斯号作为军团袭击艾欧娜尔的先锋，会使用数种不同的方式攻击玩家，以掩护军团部队的进攻。"}}
