D.ClientTexts.JournalSection[16500]={Name={["20ac39a5dd3796d0:19"]="邪能净化者"},Description={["5b6333c0dae102e9:111"]="从附近的盟友身上移除任意控制效果，并使他们免疫控制效果。"}}
