D.ClientTexts.JournalSection[16501]={Name={["f7addc66071bc5f7:21"]="注邪毁灭者"},Description={["f3c0b9bf8f68005e:135"]="持续对艾欧娜尔的精华进行炮击，直到被摧毁为止。如果不受到近战干扰，开火频率会大幅提高。\r\n此生物无法移动。"}}
D.ClientTexts.JournalSection[16502]={Name={["c06916effe5e1b58:21"]="邪能干扰器"},Description={["1146868f692dcd32:65"]="使附近的盟友获得隐形。此生物无视战斗。"}}
