D.ClientTexts.JournalSection[16555]={Name={["4057747e774063bf:9"]="终极毁灭"},Description={["ffbfa2c30348484e:365"]="在战斗过程中，帕拉克希斯号会周期性地试图歼灭区域内的所有生灵。玩家必须使用艾欧娜尔在平台上制造出来的特殊传送门进入帕拉克希斯号。进入后，玩家需要消灭一个帕拉克希斯号的审判官，然后关闭四个聚焦水晶以干扰序列。每关闭一个水晶，玩家都会根据水晶的颜色获得一层反馈效果。"}}
