D.ClientTexts.JournalSection[17002]={Name={["78907ad53eef6146:16"]="卡兹格罗斯的援助"},Description={["de113679a4abbc7e:163"]="当卡兹格罗斯获得至少20个泰坦精华时，他会开始引导泰坦之铸。\r\n\r\n玩家可以收集灵魂世界内的泰坦能量微粒，帮助卡兹格罗斯获得泰坦能量。"}}
