D.ClientTexts.JournalSection[16992]={Name={["8b59e4f86fd8290b:20"]="重组模块"},Description={["18bac5d53f5c9880:122"]="重组模块被创建后，就会启动初始化序列。\r\n\r\n当它们的生命值归零后，将会施放重组脉冲。"}}
D.ClientTexts.JournalSection[16993]={Name={["5702f8644808f825:9"]="第55部分"}}
D.ClientTexts.JournalSection[16995]={Name={["5702f8654808f826:9"]="56部分"}}
D.ClientTexts.JournalSection[16996]={Name={["0bd72c0206c54b5b:10"]="艾欧娜尔的援助"}}
D.ClientTexts.JournalSection[16999]={Name={["5702f8814809f860:9"]="第61部分"}}
D.ClientTexts.JournalSection[17000]={Name={["c7a16409e0e19a70:14"]="灵魂世界"}}
D.ClientTexts.JournalSection[17001]={Name={["808b00829e8473b1:14"]="饥饿灵魂"},Description={["171892395c6b2c66:144"]="阿古斯的怒火释放出饥饿灵魂，他们在灵魂世界游荡，如果接触到任何鬼魂就会发生爆炸，对附近的所有鬼魂施加灵魂引爆效果。"}}
D.ClientTexts.JournalSection[17004]={Name={["5702f8864809f865:9"]="第66部分"}}
D.ClientTexts.JournalSection[17005]={Name={["a0e9953be132e7f6:19"]=S[15844]},Description={["8ea320df4e12b430:231"]="当重组模块完成一次重组脉冲后，它们的泰坦能量会被释放到灵魂世界，成为泰坦能量微粒。玩家可以进入灵魂世界收集微粒，给予卡兹格罗斯泰坦能量，为他的泰坦之铸技能充能。"}}
D.ClientTexts.JournalSection[17006]={Name={["5702f8884809f867:9"]="第68部分"}}
D.ClientTexts.JournalSection[17016]={Name={["5702f8654808f826:9"]="第56部分"}}
D.ClientTexts.JournalSection[17017]={Name={["5702f8644808f825:9"]="第55区"}}
D.ClientTexts.JournalSection[17018]={Name={["5702f8634808f824:9"]="第54部分"}}
D.ClientTexts.JournalSection[17031]={Name={["5702f8264806f7ab:9"]=S[17643]}}
D.ClientTexts.JournalSection[17032]={Name={["5702f83e4807f7e1:9"]=S[17644]}}
D.ClientTexts.JournalSection[17035]={Name={["c71cdddb6df145ac:17"]="军团大军"},Description={["8fb3c3620a0ec5f9:138"]="这些生物将迁跃至不同地点，并直接冲向艾欧娜尔的精华。如果他们抵达精华旁，将持续对她造成伤害直到被击败为止。"}}
D.ClientTexts.JournalSection[17036]={Name={["001ee7af9aa38e98:8"]=S[11258]},Description={["d522596905fe4542:56"]="燃烧军团的标准步兵单位。移动速度和生命值都不算出众。"}}
D.ClientTexts.JournalSection[17037]={Name={["002e0a7ad13c3e37:8"]="恶魔犬"},Description={["3ac8de8c5d0767d1:67"]="这些燃烧军团的猎犬移动速度极快，但生命值低于恶魔卫士。"}}
D.ClientTexts.JournalSection[17038]={Name={["a2ec506d94505fa2:7"]=S[20728]},Description={["4bc393193b390824:61"]="这些燃烧军团的精英单位移动速度较慢，但生命值极高。"}}
D.ClientTexts.JournalSection[17039]={Name={["c645fcb477f1d1ad:16"]=S[21548]},Description={["d40d6f4f201a01a8:56"]="这些魔蝠能够飞行，会从空中接近艾欧娜尔的精华。"}}
D.ClientTexts.JournalSection[17040]={Name={["5702f8444807f7e7:9"]=S[17650]}}
D.ClientTexts.JournalSection[17041]={Name={["5702f8844809f863:9"]="第64区"}}
D.ClientTexts.JournalSection[17042]={Name={["5702f8854809f864:9"]="第65区"}}
D.ClientTexts.JournalSection[17043]={Name={["5702f8864809f865:9"]="第66区"}}
D.ClientTexts.JournalSection[17044]={Name={["5702f8874809f866:9"]="第67区"}}
D.ClientTexts.JournalSection[17045]={Name={["5702f8884809f867:9"]="第68区"}}
D.ClientTexts.JournalSection[17046]={Name={["63470d24fac96deb:13"]=S[1438]}}
D.ClientTexts.JournalSection[17047]={Name={["5702f81d4806f7a2:9"]=S[17634]}}
D.ClientTexts.JournalSection[17048]={Name={["5702f7fd4805f764:9"]=S[17623]}}
D.ClientTexts.JournalSection[17049]={Name={["5702f7fe4805f765:9"]=S[17624]}}
D.ClientTexts.JournalSection[17050]={Name={["d5338479e409bdf0:19"]=S[16850]},Description={["8df44ddaab1ec313:333"]="艾欧娜尔使生命缚誓者的恩赐绽放，拯救玩家。生命缚誓者的恩赐存活时，玩家可以在死亡后任意释放灵魂。如果玩家以幽灵形态移动到树旁，将会复活并消耗生命缚誓者的恩赐的一部分生命能量。\r\n\r\n生命缚誓者的恩赐的生命能量枯竭时，它将成为生命缚誓者的凋零之赐。"}}
D.ClientTexts.JournalSection[17051]={Name={["2e5199b5d89173be:27"]=S[16849]},Description={["eaab6f5fb58ed7e0:113"]="玩家可以治疗生命缚誓者的凋零之赐。此外，当玩家使用它复活时，将使其受到凋零之根的影响。"}}
