D.ClientTexts.JournalSection[17579]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["c04cb93e1c72cf37:318"]="米米尔隆并不会直接加入战斗，而是用他的发明与敌人交战。巨兽二型是一种致命的载具，可以对坦克发动强力攻击，VX-001会使用火箭冲击和激光弹幕，空中指挥单位会在空中与敌人交战，最后，V0-L7R-0N单位会登场，它集合了米米尔隆所有发明的力量。"}}
