D.ClientTexts.Adventure[8]={Name={["70209a1cd08c1ec3:9"]="灰谷"},Description={["053bcaa37e90fb2c:63"]="将暗夜精灵赶出灰谷，夺取山谷中的资源，为了部落！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[9]={Name={["751662228bcd5415:14"]="哀嚎洞穴"},Description={["6a491df5f8114108:65"]="深入哀嚎洞穴，对抗邪恶的毒牙德鲁伊。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[10]={Name={["c4b673efd32388bc:9"]="死亡矿井"},Description={["e3d75384f6a92f71:85"]="探索西部荒野废弃已久的地下矿井，迪菲亚兄弟会的非法叛军在那里盘踞。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[12]={Name={["c8ddecec368bb4b9:14"]="影牙城堡"},Description={["54c63b5cd4394bd1:99"]="废弃的城堡俯视着整个银松森林，一支由堕落的吉尔尼斯贵族掌控的势力就盘踞在这座黑暗的堡垒中。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[13]={Name={["3e5ddc79392ce0a6:12"]="战歌峡谷"},Description={["debce86a9b37603b:63"]="在夺旗战中为部落占领战歌峡谷。"},Button={["0adb9f09aa98e798:13"]=S[3863]}}
D.ClientTexts.Adventure[14]={Name={["b2f53f4bad8e3614:11"]="阿拉希盆地"},Description={["3bb0436b5fd5e1e0:75"]="在以争夺资源为主题的战场中，与联盟的玩家争夺阿拉希盆地的控制权。"},Button={["0adb9f09aa98e798:13"]=S[3863]}}
D.ClientTexts.Adventure[15]={Description={["520bb13c1fc5b871:16"]="战战战！"},Button={["e61a3567de1993d2:11"]="加入PvP队列"},Reward={["00700ceb8eb0c80e:6"]="好东西"}}
D.ClientTexts.Adventure[16]={Description={["ca9062b738b3c094:9"]="任务测试"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[17]={Name={["1cd3bad6c34d8d33:13"]="怒焰裂谷"},Description={["04d42d05a1abdf74:80"]="与盘踞在奥格瑞玛地下火山洞穴中的燃刃教徒展开激战！"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[18]={Name={["00ef6f349a4d9fad:8"]="悬槌堡"},Description={["6f81fdd2fa35905b:63"]="攻打象征着食人魔帝国权力的王座，悬槌堡！（随机团队）"},Button={["ac6a261591eba774:8"]=S[3862]}}
D.ClientTexts.Adventure[19]={Name={["8dba3898cfe9f9c5:16"]=S[22131]},Description={["59f1e237d993fae6:97"]="黑石铸造厂是钢铁部落的军事中心。组队拿下这个团队副本！（随机团队）"},Button={["ac6a261591eba774:8"]=S[3862]}}
D.ClientTexts.Adventure[20]={Name={["140a25064844d685:15"]=S[7720]},Description={["44285d61b8ed0efc:107"]="地狱火堡垒的钢铁部落已经跟古尔丹还有燃烧军团勾结在了一起。组队征讨他们！（随机团队）"},Button={["ac6a261591eba774:8"]=S[3862]}}
D.ClientTexts.Adventure[21]={Name={["78233436435568b7:13"]="随机地下城"},Description={["7d1d323b8f9c28b0:63"]="完成德拉诺之王随机地下城，为你的角色提升装备！"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[22]={Name={["140a25064844d685:15"]=S[7720]},Description={["7b4bfea5df6fb7aa:113"]="地狱火堡垒的钢铁部落已经跟古尔丹还有燃烧军团勾结在了一起。组队征讨他们！（普通难度）"},Button={["ac6a261591eba774:8"]=S[3862]}}
D.ClientTexts.Adventure[23]={Name={["470e40620d9b133b:20"]="既定命运印记"},Description={["9681ae9266964899:116"]="既定命运印记让你在团队副本中获得额外的拾取机会。从战争之矛的命运扭曲者提拉尔那里获取它们！"}}
D.ClientTexts.Adventure[24]={Name={["baec7c153ef9b6f4:21"]="既定命运印记"},Description={["3837630f4c056612:119"]="既定命运印记让你在地狱火团队副本中获得额外的拾取机会。从暴风之盾的命运扭曲者赛瑞斯那里获取它们！"}}
D.ClientTexts.Adventure[25]={Name={["06c1778162b723a6:12"]="藏宝图"},Description={["3ba557f210835445:103"]="每完成一个区域，都可以从暴风之盾的鸦人流亡者格拉吉斯那里买到藏宝图。"}}
D.ClientTexts.Adventure[26]={Name={["06c1778162b723a6:12"]="藏宝图"},Description={["3ab0038ddee381b0:100"]="每完成一个区域，你都可以从战争之矛的鸦人流亡者瑟卡那里买到藏宝图。"}}
D.ClientTexts.Adventure[27]={Name={["71a6a3f18cb00122:18"]="随机战场"},Description={["576862ad69e511b4:44"]="在随机战场中与其他玩家展开激战！"},Button={["0adb9f09aa98e798:13"]=S[3863]}}
D.ClientTexts.Adventure[29]={Name={["dedf1fb922f0e8ba:16"]="银松森林"},Description={["c2b28db710db5552:65"]="协助被遗忘者统帅部征服吉尔尼斯的港口，为了部落！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[30]={Name={["a0b277a335d27aa6:8"]="瓦丝琪尔"},Description={["24bacb9de4582daa:81"]="与舰队一同出发，占领联盟首都暴风城近海处的一座新岛屿！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[31]={Name={["93f396906e11a5eb:10"]="海加尔山"},Description={["ca13801b7503bdea:92"]="死亡之翼的爪牙已经展开了对世界之树的攻击。我们的盟友塞纳里奥议会需要你的帮助！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[32]={Name={["17e317f3c69f1754:8"]="深岩之洲"},Description={["c0924aeeebd1e4e7:74"]="萨尔和大地之环展开了对元素位面深岩之洲的突袭，他们需要你的帮助！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[33]={Name={["953a1d6e7c25551f:18"]=S[10306]},Description={["5e19a983b2d18f6c:68"]="加入被遗忘者的战争机器，进军希尔斯布莱德。为了部落！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[34]={Name={["852f62e2a58b8faf:15"]="北贫瘠之地"},Description={["a2dcab1a3e8f4edb:84"]="北贫瘠之地遭到了野猪人和半人马的侵袭，我们需要你的帮助！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[35]={Name={["5381b44f51942e42:7"]="艾萨拉"},Description={["9676d1544589e15d:92"]="击退联盟军队，占领艾萨拉。为了部落的荣耀！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[36]={Name={["3f5abfab7017a1a6:15"]="千针石林"},Description={["5d15265b9309e83c:81"]="加入部落的军队，与占据千针石林的恐怖图腾叛党作战。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[37]={Name={["cf6534f77b76d7dc:7"]="塔纳利斯"},Description={["332041cda0046162:83"]="帮助部落和锈水财阀在塔纳利斯站稳脚跟，别让联盟抢先了！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[38]={Name={["a352cc632a846ed0:7"]="菲拉斯"},Description={["74420c3080fd39bf:76"]="帮助部落清剿菲拉斯密林中的联盟和恐怖图腾。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[39]={Name={["b457bca7c6eadae2:13"]="安戈洛环形山"},Description={["f8913b90d9d7d311:82"]="与马绍尔探险队的成员一道揭开安戈洛环形山的秘密。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[40]={Name={["33836cfa97fca9e5:8"]="希利苏斯"},Description={["40fa648319a5fc3c:78"]="我们的塞纳里奥盟友需要你帮忙击退希利苏斯的暮光之锤。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[41]={Name={["419ea14a18c1f5ed:19"]="石爪山脉"},Description={["aac2546b25091ade:97"]="帮助石爪山脉的部落大军击退联盟入侵者，保护我们的人民。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[42]={Name={["a2f258359418571a:7"]="费伍德森林"},Description={["7f788f3bca0f3b94:94"]="塞纳里奥议会需要你的帮助，夺回被恶魔及它们的腐化生物控制了的费伍德森林。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[43]={Name={["e38b68d1560d1232:12"]="冬泉谷"},Description={["30ca2c279cd1af32:102"]="冬泉谷的多诺瓦·雪山找到了一条能彻底解决冬泉熊怪威胁的妙计。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[44]={Name={["387b2d056c4d7174:8"]="凄凉之地"},Description={["4bd30154574f3165:92"]="凄凉之地的部落勇士们需要你帮忙对付当地的联盟军队和古代恶魔。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[45]={Name={["a3b1a42a9f0a4537:15"]="南贫瘠之地"},Description={["f42b1557170e00ea:105"]="联盟最近在贫瘠之地取得了多次胜利，我们的补给线正受到敌人的威胁。我们必须阻止他们！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[46]={Name={["1fbe85b661fb782f:15"]="尘泥沼泽"},Description={["d56b54bf826ac710:92"]="尘泥沼泽充斥着各式各样的敌人，当地的联盟军队也异常强大，十分危险。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[47]={Name={["108124ecdd9aa7a5:5"]="奥丹姆"},Description={["d979297461498f9f:103"]="据古代文卷记载，奥丹姆埋藏着超乎想象的财富和宝藏。以部落的名义去征用它们！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[48]={Name={["43e0959c91ca8d59:10"]="幽魂之地"},Description={["00d02e11a5c71ae6:104"]="在幽魂之地，我们需要击退无穷无尽的天灾入侵者，并让被遗忘者帮助我们对抗天灾军团。这一切都需要你的帮助。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[49]={Name={["1dc61930c4d331a1:15"]="阿拉希高地"},Description={["3a368e44043f0bb7:85"]="黑暗女王的军队需要你的帮助以拓张部落的疆土，并赶走联盟的入侵者。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[50]={Name={["4d356d81e1ccad74:11"]="辛特兰"},Description={["8eff80947ceed2b1:99"]="辛特兰的蛮锤矮人正式投靠了联盟。去击败他们！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[51]={Name={["94d8659d50681aa4:18"]="西瘟疫之地"},Description={["1eb8c5966969d057:97"]="联盟军队开进了废墟之城安多哈尔。一定要在他们站稳脚跟前阻止他们！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[52]={Name={["8be2774773b0de32:18"]="东瘟疫之地"},Description={["4ee12f4f5b98571e:107"]="银色北伐军强化了他们在东瘟疫之地的兵力，他们需要你的帮助以巩固当前的胜利。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[53]={Name={["08d5149ebbbc55e3:8"]="荒芜之地"},Description={["e5961a583ad09ec1:75"]="联盟拼命想要在荒芜之地站稳脚跟。你要不惜一切代价阻止他们！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[54]={Name={["4d44fa421eaa7689:12"]="灼热峡谷"},Description={["496b33aa26fddec5:86"]="碎手氏族的报告中说灼热峡谷的黑铁矮人似乎正在策划一场战争。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[55]={Name={["8a4e46dee9241f5f:14"]="燃烧平原"},Description={["d08da5e3b465fd7a:81"]="伊崔格之子阿里乌克需要你帮助他阻止黑石兽人的攻势。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[56]={Name={["927c7176df1b6331:12"]="诅咒之地"},Description={["adae43b231374e81:106"]="巨槌要塞的部落指挥官奥克莉拉要你帮忙镇压造反的食人魔。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[57]={Name={["ec91632141750398:14"]="悲伤沼泽"},Description={["8b6cb1606094f22f:79"]="快去说服贸易巨头银罐继续为我们的战士提供武器和军火吧！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[58]={Name={["9a38fee8d5e117bd:25"]="北荆棘谷"},Description={["06a542bb3e449824:80"]="北荆棘谷的指挥官需要你帮忙确保补给线的畅通。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[59]={Name={["1b60d97fb057903a:22"]="荆棘谷海角"},Description={["06e292320d70b9b9:99"]="荆棘谷海角的我方军队需要你帮忙清理丛林里盘踞的海盗和纳迦。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[60]={Name={["7d9b853c9712f419:7"]="外域"},Description={["be7b5c1f769768b6:84"]="我们在残破的外域抗击燃烧军团，需要借助你的战斗技巧。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[61]={Name={["cdc01159572fc30e:9"]="诺森德"},Description={["ab1c3d9f7beac4a6:92"]="诺森德的战歌远征军需要你帮助他们抵挡来自亡灵天灾的持续威胁。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[62]={Name={["15162943b13a8d76:17"]="暮光高地"},Description={["5ad909b99324545a:71"]="大酋长计划对暮光高地发动一场庞大的攻势，他需要你的帮助！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[63]={Name={["0624cac99099df8c:17"]="赤脊山"},Description={["456086a4d5f19c47:67"]="赤脊山的联盟兵力捉襟见肘，他们需要你的帮助。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[64]={Name={["d5eb7002070953c3:14"]="辛特兰"},Description={["c109c360b12164dd:98"]="联盟的新同胞现在需要你的帮助。部落入侵者威胁到了他们心爱的家园，快去把这些敌人赶跑。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[65]={Name={["c1b52b27c31b9b6a:8"]="西部荒野"},Description={["5955b89f2a0d32a0:123"]="为了争夺食物和栖身之处，西部荒野的犯罪率激增。假如你想要帮助联盟，这地方会是个很好的开始。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[66]={Name={["07dcdc55c606b1b6:8"]="暮色森林"},Description={["3e26b7566f1edda1:51"]="暮色森林的居民们迫切需要你的帮助！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[67]={Name={["a0b277a335d27aa6:8"]="瓦丝琪尔"},Description={["7bf4a4a156efcd8c:97"]="最近我们在暴风城港口近海处的商船多次遭到部落的攻击。我们必须迅速还以颜色。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[68]={Name={["93f396906e11a5eb:10"]="海加尔山"},Description={["048556e1100b28ba:128"]="海加尔山需要你的帮助。塞纳里奥议会报告说，死亡之翼展开了一场针对世界之树的毁灭性攻势！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[69]={Name={["17e317f3c69f1754:8"]="深岩之洲"},Description={["b1d4016547f0a82e:124"]="大地之环需要你的帮助！他们报告说深岩之洲的元素位面即将与我们的世界发生碰撞，这会毁灭艾泽拉斯的所有生命！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[70]={Name={["410d5228847bbcf7:9"]="黑海岸"},Description={["c647cfa24c22f313:77"]="洛达内尔的居民需要你帮忙保护他们的城镇免受暮光之锤的攻击。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[71]={Name={["70209a1cd08c1ec3:9"]="灰谷"},Description={["51b9cbc2205339bf:96"]="绝不能姑息部落对灰谷的侵略行径！快去赶走这些入侵者，让这座神圣的森林恢复宁静。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[72]={Name={["3f5abfab7017a1a6:15"]="千针石林"},Description={["7e28bd4957542296:98"]="千针石林的哨兵部队需要你帮助他们击退控制了这个区域的恐怖图腾袭击者。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[73]={Name={["cf6534f77b76d7dc:7"]="塔纳利斯"},Description={["34772df4c3b4ede1:107"]="联盟需要你帮忙说服塔纳利斯的贸易巨头，让他同意我们开采这座沙漠中价值连城的资源。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[74]={Name={["a352cc632a846ed0:7"]="菲拉斯"},Description={["7ba3cb931bc568ac:84"]="菲拉斯的联盟部队需要你帮忙对抗我们的敌人：部落和恐怖图腾。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[75]={Name={["b457bca7c6eadae2:13"]="安戈洛环形山"},Description={["7731e4cbc2e1bd42:97"]="联盟要你协助马绍尔探险队，帮助他们揭开安戈洛环形山的奥秘。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[76]={Name={["33836cfa97fca9e5:8"]="希利苏斯"},Description={["8f94b7ad96a5bf8c:101"]="位于希利苏斯的塞纳里奥议会盟军需要你帮忙击退暮光之锤的攻势。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[77]={Name={["387b2d056c4d7174:8"]="凄凉之地"},Description={["c4c6f315ec0a7fb2:88"]="我们在凄凉之地那些英勇的士兵们被恶魔和部落的军队包围了，他们需要你的帮助。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[78]={Name={["419ea14a18c1f5ed:19"]="石爪山脉"},Description={["4a41f32c959f4eff:66"]="部落军队意图向石爪山推进，必须阻止他们！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[79]={Name={["a2f258359418571a:7"]="费伍德森林"},Description={["abd295b2951d13af:92"]="翡翠圣地需要你的帮助，将费伍德森林从恶魔势力的笼罩下解放出来。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[80]={Name={["e38b68d1560d1232:12"]="冬泉谷"},Description={["a090c98e152f8251:85"]="冬泉谷的多诺瓦·雪山需要你帮助她消除冬泉熊怪的威胁。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[81]={Name={["a3b1a42a9f0a4537:15"]="南贫瘠之地"},Description={["e9a1ae2bc0db6d1c:106"]="联盟的战士们在南贫脊之地捷报频传。我们需要你的力量以巩固胜利果实！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[82]={Name={["1fbe85b661fb782f:15"]="尘泥沼泽"},Description={["5a9556137288d436:98"]="你需要协助军情七处的加莉亚·哈斯汀，消除来自塞拉摩内外的威胁。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[83]={Name={["108124ecdd9aa7a5:5"]="奥丹姆"},Description={["ea0732bc1b063a9f:76"]="成为有史以来第一批踏入奥丹姆的探险者，并以联盟的名义发掘这座光辉古城中的财宝！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[84]={Name={["996a476f5ee164ea:13"]="秘血岛"},Description={["0ee9ad0c1e95e1a1:101"]="秘血岛的居民需要你帮助他们对付奸诈的血精灵和岛上横行的怪物。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[85]={Name={["c3770827d7a1b882:8"]="湿地"},Description={["00beb3a25e9c3bcb:106"]="经历了大灾变的摧残，湿地现在遍布着野兽、兽人掠夺者和野蛮的豺狼人。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[86]={Name={["467887fae1e214a7:9"]="洛克莫丹"},Description={["5329f8d4b9b2fdb1:108"]="巨石水坝被毁后，矮人巡山人们有些应接不暇了。他们迫切需要援助！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[87]={Name={["1dc61930c4d331a1:15"]="阿拉希高地"},Description={["e765e039d2472e24:72"]="阿拉希高地需要你的协助。我们要恢复激流堡古城的荣光！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[88]={Name={["94d8659d50681aa4:18"]="西瘟疫之地"},Description={["3edf8ee57605fe04:175"]="我们在安多哈尔取得了胜利，但旋即遭到了被遗忘者的反击。我们需要你的帮助以击退当地的部落和天灾，夺回西瘟疫之地的安多哈尔。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[89]={Name={["8be2774773b0de32:18"]="东瘟疫之地"},Description={["02628f6802319545:84"]="银色北伐军需要你的帮助，从天灾手中夺回东瘟疫之地。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[90]={Name={["08d5149ebbbc55e3:8"]="荒芜之地"},Description={["56cef1a8aefd967d:93"]="我们需要你帮忙调查死亡之翼对荒芜之地造成的破坏，以及那里部落军队的部署情况。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[91]={Name={["4d44fa421eaa7689:12"]="灼热峡谷"},Description={["fa8d6e1c9f0eaad7:97"]="军情七处报告说灼热峡谷的黑铁矮人正在策划一次进攻。快去阻止他们，否则就迟了！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[92]={Name={["8a4e46dee9241f5f:14"]="燃烧平原"},Description={["4d6462ae2b038fa5:76"]="我们急需你前往燃烧平原，终结黑石兽人的威胁！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[93]={Name={["927c7176df1b6331:12"]="诅咒之地"},Description={["e1a2723c409c5f6f:83"]="守望堡急需你的帮助，以遏制部落深入诅咒之地的脚步。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[94]={Name={["ec91632141750398:14"]="悲伤沼泽"},Description={["48dc11db7b2cfd2a:98"]="去和悲伤沼泽的贸易巨头银罐沟通一下，确保他能稳定地向联盟供应军火！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[95]={Name={["9a38fee8d5e117bd:25"]="北荆棘谷"},Description={["c1f72c1a004cf82b:122"]="库尔森上校背叛暴风城已经是好几年前的事了，但他的命运依然是个谜。帮助幸存者了解上校的近况。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[96]={Name={["1b60d97fb057903a:22"]="荆棘谷海角"},Description={["9eaf6cce57ce1efb:114"]="荆棘谷海角的探险者协会需要你的帮助，以保护他们的挖掘场和考古发现不被食人魔袭击。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[97]={Name={["7d9b853c9712f419:7"]="外域"},Description={["fb81eb1491c1227d:108"]="燃烧军团的恶魔大军从外域发动了入侵！为了对抗他们，远征军需要你的帮助。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[98]={Name={["cdc01159572fc30e:9"]="诺森德"},Description={["43ce1a67f2f6d37e:111"]="无畏远征军需要你帮助他们控制住诺森德的天灾军团，守护文明世界。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[99]={Name={["15162943b13a8d76:17"]="暮光高地"},Description={["bdb32413297676e6:75"]="瓦里安国王需要一位可靠的英雄，帮助他执行一项至关重要的任务。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[100]={Name={["0b319cc5670a21f0:8"]="潘达利亚"},Description={["1649186b0ae76002:71"]="快去格罗玛什要塞，向新酋长宣誓效忠吧！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[101]={Name={["857b2ca91b5f4e4a:20"]="四风谷"},Description={["186c70546d372c67:101"]="据当地人说，有一名强大的熊猫人武僧正在四风谷旅行。你能否赢得他的好感呢？"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[102]={Name={["4d77b7357306a838:13"]="昆莱山"},Description={["1805c295e4bd8268:89"]=S[18004]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[103]={Name={["fe24c1e11398f584:15"]="螳螂高原"},Description={["8bad0dbffbeb935e:103"]="影踪派正浩浩荡荡地跨越长城进入螳螂高原。快去协助他们展开突击行动吧！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[104]={Name={["78d1663cf33959d3:11"]="恐惧废土"},Description={["2a6d7ab237704021:103"]="守护长城的影踪派正招募援军以对抗恐惧废土的螳螂妖大军。他们需要你的帮助。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[127]={Name={["4f9533fca66aec11:8"]="玛拉顿"},Description={["e2e4ea50440c83a1:82"]="进入玛拉顿的水晶洞穴，据说那里盘踞着一个恶魔。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[105]={Name={["7c66657fd755f592:21"]="锦绣谷"},Description={["d1e3bbbbd7c8452a:205"]="锦绣谷遭到了攻击。安度因·乌瑞恩王子现已前往昆莱山白虎寺，请求潘达利亚的人民允许外来者进驻这座山谷，以在必要的时候提供援手。他需要你的帮助。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[106]={Name={["7c66657fd755f592:21"]="锦绣谷"},Description={["251363bb65ccf60a:94"]="锦绣谷遭到了攻击。烈日行者德兹科现已前往昆莱山白虎寺。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[107]={Name={["267ffe50d6e2985f:7"]="德拉诺"},Description={["fabed94d3366e762:104"]=S[8057]},Button={["b2061be5f7b48b80:10"]=S[10492]},Continue={["304db2eec967a921:79"]=S[10359]}}
D.ClientTexts.Adventure[108]={Name={["267ffe50d6e2985f:7"]="德拉诺"},Description={["fabed94d3366e762:104"]=S[8057]},Button={["b2061be5f7b48b80:10"]=S[10492]},Continue={["304db2eec967a921:79"]=S[10359]}}
D.ClientTexts.Adventure[109]={Name={["fc24a5c79bb93eb0:8"]="戈尔隆德"},Description={["031b71751ee88ec6:122"]="指挥官，杜隆坦打算带领一支突击小分队进入戈尔隆德，对当地的钢铁部落要塞发动反击。他需要你的援助。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[110]={Name={["fc24a5c79bb93eb0:8"]="戈尔隆德"},Description={["7766053a45cdf9d7:127"]="指挥官，伊瑞尔和玛尔拉德打算带领一支突击小分队进入戈尔隆德，对当地的钢铁部落要塞发动反击。他需要你的援助。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[111]={Name={["cf40c92cecbf4245:7"]="塔拉多"},Description={["4fa0e5ceae7fe5a5:112"]=S[20948]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[112]={Name={["0b00a7cf96927da6:12"]="阿兰卡峰林"},Description={["53b8ad9580438e0e:105"]="阿兰卡峰林现在遍地都是战火与暴乱。许多鸦人流亡者正成群结队地逃离那里，他们可以成为我们极有价值的盟友。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[113]={Name={["0b00a7cf96927da6:12"]="阿兰卡峰林"},Description={["f27a9878ed25ce2b:125"]="指挥官，阿兰卡峰林现在遍地都是战火与暴乱。许多鸦人流亡者正成群结队地逃离那里，他们可以成为我们极有价值的盟友。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[114]={Name={["cf40c92cecbf4245:7"]="塔拉多"},Description={["4fa0e5ceae7fe5a5:112"]=S[20948]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[115]={Name={["011227a0a9987e19:7"]="纳格兰"},Description={["38938afa2b798bcd:98"]="萨尔正在征集援助，以在纳格兰建立一座要塞。那里是可怕的战歌氏族和火刃氏族的家园。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[116]={Name={["011227a0a9987e19:7"]="纳格兰"},Description={["4da7d1c28a54a7a3:106"]="守备官伊瑞尔正在征集援助，以在纳格兰建立一座要塞。那里是可怕的战歌氏族和火刃氏族的家园。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[117]={Name={["4384a96305cf469a:19"]="准备进攻！"},Description={["750a3a5219ba7441:99"]="大酋长沃金莅临你的要塞，来和你共同商讨进攻塔纳安丛林的战略。你的部队准备好了吗？"},Button={["b2061be5f7b48b80:10"]=S[10492]},Continue={["6623c31f67ace7de:72"]="在你的要塞中与酋长沃金交谈，商讨进攻塔纳安丛林的计划。"}}
D.ClientTexts.Adventure[118]={Name={["b2f53f4bad8e3614:11"]="阿拉希盆地"},Description={["795007e468d02455:72"]="在以争夺资源为主题的战场中，与部落的玩家争夺阿拉希盆地的控制权。"},Button={["0adb9f09aa98e798:13"]=S[3863]}}
D.ClientTexts.Adventure[119]={Name={["4384a96305cf469a:19"]="准备进攻！"},Description={["bc07a397aa0b0c16:96"]="瓦里安·乌瑞恩国王莅临你的要塞，来和你共同商讨进攻塔纳安丛林的战略。你的部队准备好了吗？"},Button={["b2061be5f7b48b80:10"]=S[10492]},Continue={["989d46453304a918:72"]="在你的要塞中与瓦里安·乌瑞恩国王交谈，商讨进攻塔纳安丛林的计划。"}}
D.ClientTexts.Adventure[120]={Name={["bb3511b29fb84a5b:16"]=S[22074]},Description={["19339572a1b1d9df:99"]="这座古老的暗夜精灵神庙现已被纳迦和萨特所占据。在某种古老的邪恶力量被唤醒之前击败他们。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[121]={Name={["f354a9f01a7d400f:17"]="塔纳安丛林日常任务"},Description={["7af12cb537dd7b02:96"]=S[9842]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[122]={Name={["f354a9f01a7d400f:17"]="塔纳安丛林日常任务"},Description={["7af12cb537dd7b02:96"]=S[9842]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[123]={Name={["afa6335a846b3a3d:17"]="暴风城监狱"},Description={["1efa6975f2f545f4:66"]="暴风城监狱的囚犯们打算越狱。阻止他们！"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[124]={Name={["0e5f140880f9c761:10"]="诺莫瑞根"},Description={["ea7116fca8068565:114"]="潜入被辐射污染的侏儒首都诺莫瑞根，清除在其中横行的穴居人、麻疯侏儒和机械怪兽。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[125]={Name={["70e24e27890a1740:12"]="血色大厅"},Description={["5c8ebde2f4b28efd:118"]="血色十字军最凶猛的战士们正在血色大厅中组建一支军队。在他们出击前击溃他们。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[126]={Name={["4aaff65580d5c5fc:16"]=S[18884]},Description={["ec1e95b4e5310261:99"]="攻入血色十字军的要塞血色修道院，将他们那些疯狂的领袖绳之以法。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[128]={Name={["090e3f4b2212a5b0:13"]="剃刀沼泽"},Description={["192575f47b2e6c8f:73"]="你需要深入遍布荆棘的剃刀沼泽，那里是野猪人的巢穴和要塞。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[129]={Name={["f6dfc6031c9529ce:15"]="毒菇洞穴"},Description={["130e9f1d40b1d758:90"]="深入位于地下的毒菇洞穴，净化根植于玛拉顿深处的腐蚀。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[130]={Name={["2e144ee26d4be699:14"]="地歌瀑布"},Description={["e54cb388cf3605d1:106"]="我们需要一位英雄深入玛拉顿的洞穴，终结瑟莱德丝公主和她的爪牙造成的腐蚀。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[131]={Name={["355325479bcfee86:7"]="奥达曼"},Description={["623568e76b0cb704:104"]="探索奥达曼，这座古代的泰坦城市中遍布着他们的失败作品和各种神奇的宝藏。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[132]={Name={["524fa29cea1d0717:15"]="扭木广场"},Description={["57e7887454e83f5f:88"]="进入厄运之槌东区，清除盘踞在其中的堕落古树和怪物。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[133]={Name={["aba849d1dcf4c842:11"]=S[20391]},Description={["aedef14d1b527486:101"]="我们正召集英雄前往通灵学院，对抗学院中那些可怕的通灵师以及他们的亡灵造物。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[134]={Name={["adaec487eb91fcf6:14"]="中心花园"},Description={["22705849ef5c761e:106"]="一些盲目追求重获永生的暗夜精灵招来了黑暗的诅咒。赶快进入厄运之槌的废墟，彻底终结那里的诅咒。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[135]={Name={["088e4b57c5d5edd0:13"]="剃刀高地"},Description={["94222081b861f432:110"]="这座野猪人的要塞出现了亡灵，这是令人担忧的信号，也许天灾正试图在卡利姆多建立一座据点。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[136]={Name={["9e443de70230ecf2:13"]="戈多克议会"},Description={["f66f1aa04c63c253:98"]="凶残的戈多克食人魔控制了厄运之槌的北侧，并企图利用那里蕴藏的能量。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[137]={Name={["468037bb9ddbe878:19"]="斯坦索姆－正门"},Description={["5dba9dda479d78c1:103"]="曾经辉煌的人类城市斯坦索姆现已成为一座遍布亡灵的废墟。只有最强大的英雄才敢从正门闯入。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[138]={Name={["ba85acdeece96dfb:10"]=S[17268]},Description={["a36af89c0bfbb04d:106"]="祖尔法拉克的沙怒巨魔曾经有过强大而又残忍的历史。最近他们似乎在聚集一支由亡灵组成的军队，你会站出来对抗他们吗？"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[139]={Name={["2bd8fdd6edea4ef7:26"]="斯坦索姆－后门"},Description={["b14f2ff3817d505e:103"]="我们在斯坦索姆城的废墟中找到了另一处入口，快利用它去打击城中的天灾军团吧。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[140]={Name={["785abb7b1e8df7ee:17"]="禁闭室"},Description={["cf67a8e81afed4af:93"]="黑石深渊的黑铁矮人们竟然勾结了暮光之锤教派，必须阻止他们。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[141]={Name={["155901007207a5b5:12"]=S[15701]},Description={["862315d37c5675d6:110"]="深入这座沉没的神庙，终结盘踞在其中的被腐化的绿龙守卫，并阻止那些阿塔莱巨魔祭祀。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[142]={Name={["a1d24619cc48c574:15"]="黑石深渊"},Description={["06283ff19c6a54ee:93"]="深入黑铁矮人的首都，击败他们邪恶的领袖：索瑞森大帝。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[143]={Name={["e639359deff858fc:19"]="黑石塔下层"},Description={["78f1b0d29fd24d17:104"]="一支所谓的“部落”正聚集在酋长雷德·黑手的旗下，击败他们的部队，还有他们的黑龙盟友。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[144]={Name={["f6123fba56a502f5:16"]="地狱火城墙"},Description={["6eb82d22d761c9d3:86"]="向地狱火半岛上那座几乎坚不可摧的邪能部落基地展开突击。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[145]={Name={["498d0dba21ac49af:15"]="鲜血熔炉"},Description={["a1fc5572507bbf5f:95"]="邪能部落正对他们自己的人民展开各种黑暗而可怕的实验，想要制造出凶猛的士兵用于作战。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[146]={Name={["91df1c37edf42f20:12"]="奴隶围栏"},Description={["37badaf58ef97948:74"]="赞加沼泽的奴隶围栏中，邪恶的盘牙纳迦抓捕了许多奴隶，快去解放他们。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[147]={Name={["f113967cbd7e2e53:11"]="幽暗沼泽"},Description={["7ba779b07b8a40af:75"]="进入幽暗沼泽，对抗来自深渊中的古怪的真菌生物。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[148]={Name={["31d8f314c5fbcbfd:10"]="法力陵墓"},Description={["2f80e25daa35015e:117"]="节点亲王沙法尔手下的虚灵正在亵渎奥金顿的德莱尼陵墓，阻止他们。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[149]={Name={["8e6c30e8f1d9c5af:14"]="奥金尼地穴"},Description={["87a2ecd89b00492d:95"]="探索古老的奥金尼陵墓，击败墓中的德莱尼鬼魂，并让发狂的陵墓守卫者们安息。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[150]={Name={["74385cd08644d39d:22"]=S[20353]},Description={["8f04938728377486:104"]="穿越时空回到昔日的希尔斯布莱德丘陵，阻止邪恶势力刺杀尚未成年的萨尔。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[151]={Name={["7e9a40c808a1007b:12"]="塞泰克大厅"},Description={["49045f45027fbfd6:72"]="与控制了塞泰克大厅的强大鸦人法师们展开激战。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[152]={Name={["d810cc65c1edd38c:11"]="能源舰"},Description={["5f99506937efce80:100"]="与能源舰的血精灵展开激战，阻止他们揭开飞船中隐藏着的纳鲁秘密。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[153]={Name={["04b24f61c00eb97a:17"]=S[21942]},Description={["d43fdfe96bab3d9a:112"]="凯尔萨斯·逐日者勾结燃烧军团的行径已经暴露，他已经撤回了魔导师平台。我们必须阻止他！"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[154]={Name={["4ea881967165e0bf:11"]=S[929]},Description={["4e80a6004355345d:101"]="乌特加德城堡曾一度被认为是个荒堡，但如今维库人的脚步声再一次出现在了这座古老的大殿中。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[155]={Name={["c2c96d996b455c4e:8"]="魔枢"},Description={["2ffe88377266f16c:106"]="玛里苟斯的部队正将所有的奥术能量都导向魔枢。必须阻止他们，否则我们的世界将永远失去魔法的力量。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[156]={Name={["f72f5b0e83d61709:11"]=S[18206]},Description={["0a016c5396266952:92"]="前往艾卓-尼鲁布，这个一度辉煌的蜘蛛帝国现在已经沦落为向巫妖王效忠的亡灵聚集地。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[157]={Name={["651077539f154ebc:23"]=S[8796]},Description={["0f2d13e89dd9f4e9:101"]="深入古代地下城市安卡赫特，战胜苏醒于世界深处的可怕力量。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[158]={Name={["9c27e93fde50edd8:15"]=S[19832]},Description={["e8c31fe1022d0cfc:86"]="突袭达克萨隆要塞，战胜控制了这座要塞的亡灵军队。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[159]={Name={["b7bb1cbf06cc337e:10"]=S[17781]},Description={["1f6258dab6da8cdd:102"]="蓝龙军团意图将最可怕的囚犯释放出来，肯瑞托需要你的帮助。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[160]={Name={["14f9f577d52ab0b4:12"]="岩石大厅"},Description={["0527801652ca1383:86"]="与著名探险家布莱恩·铜须一同冒险，探索古代泰坦工厂：岩石大厅。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[161]={Name={["1558efd1e24cc478:7"]="古达克"},Description={["1d11a74d9271a53a:84"]="古达克的巨魔背叛了他们自己的神明，不惜杀戮神灵以获得其力量。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[162]={Name={["789750f2ddbea679:16"]="闪电大厅"},Description={["7bab4dc8bb0c755d:73"]="突袭洛肯的要塞，并在闪电大厅的王座前挑战他。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[163]={Name={["71de98db06dcd3ee:15"]=S[927]},Description={["56fda450d387d4ef:102"]="伊米隆国王回来了，他现在效忠于巫妖王。我们必须在伊米隆和他的军队达到全盛状态前击败他们。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[164]={Name={["1e264da1c0b25d9a:9"]="魔环"},Description={["060bb26b2fd8eaa0:107"]="魔环的蓝龙军团正将全世界的魔法输往扭曲虚空，必须阻止他们。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[165]={Name={["d5d3e40c8ab596af:22"]=S[3013]},Description={["4746964b64a8731c:109"]="穿越时空回到过去。在那个命运之日，阿尔萨斯王子率领他的军队在斯坦索姆被天灾瘟疫吞噬前进入了这座城市。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[166]={Name={["8630ada3bf0bbd26:16"]="黑石岩窟"},Description={["f96a844b12897e06:106"]="黑石山的深处，暮光之锤与死亡之翼的军队正在联手制造危险的怪物。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[167]={Name={["7f882f047bba7b6b:16"]="潮汐王座"},Description={["074708b3fcc327d8:93"]="与水元素领主耐普图隆一同对抗纳迦和上古之神势力联军的入侵。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[168]={Name={["81720758bbdca673:17"]="旋云之巅"},Description={["afd1e2d43d292663:91"]="深入气元素位面，与天空之墙的部队及风暴幼龙展开激战。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[169]={Name={["16ecdad8b38fc073:12"]="巨石之核"},Description={["ee58eafd91063ace:112"]="暮光之锤教徒和他们的元素扭曲者们防守着土元素位面的巨石之核。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[170]={Name={["a762a27d6c143d9e:20"]=S[11953]},Description={["57d773484629b0f7:108"]="尼斐塞特的托维尔追随者们身上的血肉诅咒被治愈了。现在他们威胁到了周围一带地区的和平。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[171]={Name={["9d889446b0dd6d23:9"]=S[14812]},Description={["3550a382ccea57db:107"]="暮光之锤的入侵者占据了矮人城市格瑞姆巴托，并带来了一股古老而邪恶的力量。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[172]={Name={["f0f67b79fd5cfd06:17"]=S[21522]},Description={["4280f599f900b41c:89"]="深入著名的风暴烈酒酿造厂，解决酒厂里的麻烦。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[173]={Name={["ad4f26b7dc111576:22"]="青龙寺"},Description={["23ba993ba9243238:68"]="对抗疑之煞，阻止它占据青龙寺。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[174]={Name={["371cd7f471cfa241:15"]=S[21917]},Description={["87257e18d7e565f5:108"]="潘达利亚大陆上仍占有统治地位的三支魔古部族在魔古山宫殿中聚集着力量。必须阻止他们。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[175]={Name={["be8c8582389fbb6f:18"]="影踪禅院"},Description={["7088d873ee3180e8:103"]="狂之煞、怒之煞以及恨之煞正试图腐化古老的影踪派。面对他们，阻止他们的邪恶图谋。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[176]={Name={["d558962736582dfc:18"]=S[18869]},Description={["1dd773e815c517a7:75"]="闯进可怕的血槌炉渣矿井，解放被食人魔抓来的奴隶。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[177]={Name={["56dfa0f17d140158:9"]=S[20931]},Description={["ed4322cdf6c1eeee:79"]="钢铁部落的海军舰队集结在戈尔隆德的钢铁码头。必须阻止他们。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[178]={Name={["9a9972b3697827a2:10"]="奥金顿"},Description={["4f18fecc4d499033:118"]="我们需要一位英雄，驱逐渗透进奥金顿的暗影议会势力，阻止他们利用这座古代德莱尼陵墓中蕴藏的力量来作恶。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[179]={Name={["ec65795f0a7821f2:8"]="通天峰"},Description={["77bae130c9fde567:87"]="向通天峰和那里邪恶的鸦人发动攻击，他们正利用太阳的力量对付他们的敌人。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[180]={Name={["97ff3f1140442cd4:12"]=S[15657]},Description={["21a6c9aa94b92377:134"]="肯瑞托曾试图在在永茂林地的深处建立一条向德拉诺输送物资的补给线。但他们的哨站却被凶残的原祖荆兽给摧垮了。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[181]={Name={["41d708050484e816:23"]=S[10676]},Description={["d6fa256267d294d1:119"]="在影月墓地的深处，耐奥祖酋长正在使用虚空魔法进行各种堕落的实验，折磨墓地里的灵魂。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[182]={Name={["8e54ca98d0432e73:13"]=S[10892]},Description={["7e1f0efac9f8b4af:124"]="宏伟的恐轨列车是钢铁部落战争机器的重要资源，也是勇敢的英雄们首要的攻击目标。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[183]={Name={["0807c200919060bd:19"]=S[22123]},Description={["76ed508bfc0f6e32:111"]="钢铁部落在艾泽拉斯控制了一处据点，就位于黑石塔上层。如果置之不理的话，他们就会威胁到我们堡垒和疆域。"},Button={["38f149c2bf435ed5:9"]=S[3864]}}
D.ClientTexts.Adventure[184]={Name={["f1717884feb17d8d:22"]=S[2544]},Description={["474fcd08d6dabd6b:68"]=S[6626]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[185]={Name={["f1717884feb17d8d:22"]=S[2544]},Description={["a7978931604b0d54:72"]=S[6624]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[186]={Name={["5ac172ca40fb99ff:21"]="假日活动：练习赛"},Description={["420cdbb7d3443dde:60"]="在假日活动期间与其他玩家在练习赛中对抗。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[187]={Name={["191f8306b8a1f935:24"]="假日活动：战场"},Description={["3ec52773a8e13158:63"]="在假日活动期间与其他玩家在战场上对抗！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[188]={Name={["70548eefbd4a1c44:17"]=S[4060]},Description={["cb6f08d67f1b4493:105"]="大法师卡德加非常担心德拉诺可能会给艾泽拉斯带来的威胁，他需要你的帮助来查明此事。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[189]={Name={["70548eefbd4a1c44:17"]=S[4060]},Description={["107d5b1cdfde74b7:95"]=S[8054]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[190]={Name={["70548eefbd4a1c44:17"]=S[4060]},Description={["107d5b1cdfde74b7:95"]=S[8054]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[191]={Name={["cfb13660eb032f3b:21"]="假日活动：宠物对战"},Description={["850014803d07a533:49"]="在假日活动期间参与宠物对战！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[192]={Name={["70548eefbd4a1c44:17"]=S[4060]},Description={["107d5b1cdfde74b7:95"]=S[8054]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[193]={Name={["70548eefbd4a1c44:17"]=S[4060]},Description={["107d5b1cdfde74b7:95"]=S[8054]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[194]={Name={["76ed42ab70fc9718:19"]="假日活动：地下城"},Description={["2daf64f2df1d4bef:59"]=S[6622]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[195]={Name={["c561cb95be307544:22"]="假日活动：世界任务"},Description={["6d5f1936ca18bbc3:85"]="在假日活动期间在破碎群岛完成世界任务，获得更多的奖励！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[196]={Name={["eacedba78e1f5440:10"]="练习赛"},Description={["db217106d9dc8af9:40"]="在2v2和3v3的练习赛中与其他玩家展开激战！"},Button={["15fb20771c29fd8a:14"]="加入练习赛"}}
D.ClientTexts.Adventure[197]={Name={["3e5ddc79392ce0a6:12"]="战歌峡谷"},Description={["e49b7e51305703bc:66"]="在这个夺旗战场中为联盟夺取战歌峡谷。"},Button={["0adb9f09aa98e798:13"]=S[3863]}}
D.ClientTexts.Adventure[198]={Name={["4d77b7357306a838:13"]="昆莱山"},Description={["1805c295e4bd8268:89"]=S[18004]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[199]={Name={["2891ed27da2d2ea2:8"]="美酒节"},Description={["129dbbb969329b9e:86"]="美酒节遭到了黑铁矮人的攻击！快去黑石深渊干掉他们的首领。"},Button={["470421f3f18d1866:9"]=S[9693]}}
D.ClientTexts.Adventure[200]={Name={["0053395b533ed54e:18"]="钓鱼大赛！"},Description={["92e9ce936d52a4e6:104"]="快去藏宝海湾参加荆棘谷钓鱼大赛，和其他玩家一较高下吧！比赛将在下午2点开始。"}}
D.ClientTexts.Adventure[201]={Name={["28353b20a1238577:11"]="专业"},Description={["42aaadd29c1d47c7:110"]="炼金、采矿之类的专业技能可以让你制造和采集有用的物品。去任意主城跟守卫问个路，就可以找到训练师！"}}
D.ClientTexts.Adventure[202]={Name={["5a370c033336ee82:11"]="赞加沼泽"},Description={["c0804083c6237308:71"]=S[11522]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[203]={Name={["5a370c033336ee82:11"]="赞加沼泽"},Description={["c0804083c6237308:71"]=S[11522]},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[204]={Name={["f866ae9b9d8827bc:14"]="泰罗卡森林"},Description={["a9d36121f585ce74:68"]="泰罗克森林需要你帮忙抵挡部落的敌人。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[205]={Name={["f866ae9b9d8827bc:14"]="泰罗卡森林"},Description={["3bb20b084d661c25:71"]="泰罗克森林需要你帮忙抵挡联盟的敌人。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[206]={Name={["011227a0a9987e19:7"]="纳格兰"},Description={["92dd88b60ed6081d:82"]="加拉达尔的玛格汉兽人需要帮助。赶快奔赴纳格兰，代表部落助他们一臂之力吧。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[207]={Name={["011227a0a9987e19:7"]="纳格兰"},Description={["9b85644d07dec684:63"]="国王正在号召志愿者前往纳格兰与库雷尼协商。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
