D.ClientTexts.Adventure[289]={Name={["869f4b5e52e15bd5:27"]="起义：精灵事务"},Description={["23baeadcbfd9b563:101"]="联盟和部落已抵达苏拉玛。首席奥术师塔莉萨需要你帮忙向他们介绍情况。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
