D.ClientTexts.Adventure[319]={Name={["815f0b888486d221:13"]="恶魔突袭"},Description={["7d1e3075bb57fb9a:40"]="将燃烧军团赶出破碎群岛。"}}
D.ClientTexts.Adventure[320]={Name={["1b20a353d388cd8c:17"]="神器知识"},Description={["2b03e64595e21f3c:56"]="前往你的职业大厅获取已经准备好的神器知识。"}}
D.ClientTexts.Adventure[321]={Name={["462185b2b5d05b0d:20"]="乱斗：阿拉希暴风雪"},Description={["33414c9ccbb820e1:55"]="阿拉希盆地被大雪覆盖，布满了战场迷雾。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[322]={Name={["cb4228619fc32596:21"]="乱斗：战歌总动员"},Description={["dd0e1c03b7a7d15c:84"]="战歌峡谷的战事陷入了白热化。他们在战斗中一次动用了三面旗帜以及大量特殊的强化能力。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[323]={Name={["0136aafadebbd989:13"]="乱斗：寇魔古寺"},Description={["1adb15e863000fa7:65"]="寇魔古寺气氛热烈，高速移动以及传递能量球的技能受到了热捧。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[324]={Name={["a22cbb12773613d3:18"]="乱斗：引力失效"},Description={["c82b9020744e2fcb:96"]="重力让你厌烦了？快走进风暴之眼，尝试全新的体验吧。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[325]={Name={["217e4bf91ebb92b6:18"]="乱斗：深风大灌篮"},Description={["f7f142ebcfa799a8:68"]="从地图中央开始争夺篮球，并将其投入敌人的篮框来得分吧。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[326]={Name={["d9aa18073265e5e0:18"]="乱斗：羊角之眼"},Description={["24bdc2776485fec0:52"]="没有坐骑？没关系。快去领一头山羊，加入激烈的骑战吧。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[327]={Name={["163fee638441e934:17"]="乱斗：爆棚乱战"},Description={["b2402994df06ca07:41"]="这场人数爆棚的竞技场比赛最多可容纳30名玩家同场竞技。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[328]={Name={["c6255a6ef143f523:28"]="乱斗：南海镇VS塔伦米尔"},Description={["b9afd9bbe01a94c0:49"]="回忆昔日的史诗拉锯战。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[329]={Name={["6646952bafc2dfd2:23"]="乱斗：决战影踪派"},Description={["7f5f7e21bf94b5a4:80"]="你的5人竞技场队伍将获得一位首领级的第六人。最先击败敌人的一方将获得胜利！"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[330]={Name={["8853792a2502dcc1:21"]="升级传说物品"},Description={["cb3802e7ba0819b2:66"]="与奥法工匠维迪尔合作，提升你的传说物品的威力。"},Button={["b2061be5f7b48b80:10"]=S[10492]}}
D.ClientTexts.Adventure[331]={Name={["4b61bb5e33c414c7:15"]="枭兽节"},Description={["2bd63433a169f932:95"]="今天，月光林地将举办一场有关枭兽的有趣庆典。快来看看你能学到些什么吧！"}}
D.ClientTexts.Adventure[332]={Name={["b8452907abea84c4:12"]="时尚试炼"},Description={["e15bc08a58fee76b:146"]="掸去肩甲上的征尘，加入艾泽拉斯的时尚比拼吧！与任意主城的幻化师NPC对话，参与时尚试炼！"}}
D.ClientTexts.Adventure[333]={Name={["8b85f691bf50b78e:21"]="诺莫瑞根马拉松"},Description={["5d8146bbd02cbf44:108"]="和侏儒们一起向他们百折不挠的精神致敬！跨越东部王国，从诺莫瑞根南下，一直跑到藏宝海湾！"}}
D.ClientTexts.Adventure[334]={Name={["510dfb67f8a3d2f0:22"]="舞会"},Description={["45f03ae50fcb25fc:129"]="今天，奥格瑞玛和暴风城的主拍卖行已经清场并改为了舞会！快来展示一下你们的阵营荣誉感吧！"}}
D.ClientTexts.Adventure[335]={Name={["91c020204ef85eb1:19"]="肯瑞托旅店趴"},Description={["f398d96fd4bbe430:92"]="艾泽拉斯的法师们也需要休闲。快去你所在地的酒吧，进入传送门，参加旅店趴活动吧！"}}
D.ClientTexts.Adventure[336]={Name={["f899d0830f61a17e:15"]="甲虫的召唤"},Description={["d3eabe5c93d09a0f:209"]="历史上的今天，甲虫之锣被敲响，开启了安其拉的大门。代表你的阵营收集补给品，或者击杀暮光之锤和其拉虫族的部队。获胜的阵营可以将自己的旗帜挂在甲虫之锣旁，直至年末！"}}
D.ClientTexts.Adventure[337]={Name={["1c4173505444c6bd:15"]="亮顶节"},Description={["c329976f55e43f00:122"]="今天，赞加沼泽孢子村的孢子人们将举行他们一年一度的蘑菇节。尽可能帮助他们保护伟大的弗肖，不要让她死亡！"}}
D.ClientTexts.Adventure[338]={Name={["b4c3c9feefc822a3:24"]="角鹰兽孵化日"},Description={["782e22ada5e7bb38:114"]="今天是乱羽角鹰兽孵化的日子。前往位于菲拉斯的乱羽高地，亲眼见证这一奇景吧！"}}
D.ClientTexts.Adventure[339]={Name={["25a9012218fd84bb:18"]="蝌蚪远足日"},Description={["2b90166c35ca92b1:78"]="今天，北风苔原的冬鳍部族的幼年鱼人们将完成他们穿越西部裂谷的旅程。"}}
D.ClientTexts.Adventure[340]={Name={["d3226e5df3f2b15a:21"]="春日气球节"},Description={["8df30832d7f3e381:126"]="这是一个风和日丽的日子……最适合坐着热气球观光了。快乘上热气球饱览美景，结交新朋友吧！"}}
D.ClientTexts.Adventure[341]={Name={["112a732f0327c9f2:16"]="赛艇大会"},Description={["507ddb6803812143:63"]="艾泽拉斯的居民需要休息。让我们去千针石林划船吧！"}}
D.ClientTexts.Adventure[342]={Name={["19a0fe316805f2b4:14"]="安戈洛狂欢节"},Description={["1a55135459101c77:62"]="安戈洛环形山的恐龙越来越焦躁了。该去拜访它们一下了！"}}
D.ClientTexts.Adventure[343]={Name={["eedd5e9a1ebce021:17"]="志愿军日"},Description={["bff6f322efff5efb:120"]="今天，艾泽拉斯和德拉诺的居民将共同表彰他们的保卫者所作出的贡献。向一名卫兵敬礼以表达你的敬意吧！"}}
